package com.bank.treasury.service;

import java.util.logging.Logger;

// Finds the length of the smallest window whose deposit sum meets a target.
public class LiquidityWindowFinder {
    private static final Logger log = Logger.getLogger(LiquidityWindowFinder.class.getName());

    public int smallestWindowLength(int[] deposits, int target) {
        if (deposits == null || target <= 0) return 0;
        long windowSum = 0;
        int left = 0;
        int best = Integer.MAX_VALUE;

        for (int right = 0; right < deposits.length; right++) {
            windowSum += deposits[right];          // expand on the right
            while (windowSum >= target) {          // qualifying window
                best = Math.min(best, right - left + 1);
                windowSum -= deposits[left];       // shrink from the left
                left++;
            }
        }
        int result = (best == Integer.MAX_VALUE) ? 0 : best;
        final int r = result;
        log.info(() -> "Smallest window length meeting target " + target + " = " + r);
        return result;
    }
}
