package com.bank.treasury;

import com.bank.treasury.service.LiquidityWindowFinder;
import java.util.Arrays;
import java.util.logging.Logger;

public class LiquidityWindowDemo {
    private static final Logger log = Logger.getLogger(LiquidityWindowDemo.class.getName());

    public static void main(String[] args) {
        int[] deposits = {2, 1, 5, 2, 3, 2};
        int target = 7;
        log.info(() -> "Deposits: " + Arrays.toString(deposits) + ", target=" + target);

        LiquidityWindowFinder finder = new LiquidityWindowFinder();
        int length = finder.smallestWindowLength(deposits, target);

        log.info(() -> "Shortest stretch to raise " + target + " spans " + length + " day(s).");
    }
}
